// Spaces: the small web page each challenge (and each member) gets, generated by the
// codegen model from a plain-language request. Generation runs in the background;
// pages are served from stored HTML with fresh data inlined, so they keep working
// when the model is unavailable.

import type { SpaceStatus } from "@/lib/shared/types";
import type { UserRow } from "./auth";
import { all, one, run, tx } from "./db";
import { buildSpaceHtml } from "./ai/codegen";
import { getChallenge, requireCreator, requireMember, type ChallengeRow } from "./domain/challenges";
import { recordActivity } from "./domain/feed";
import { AppError, id, nowIso } from "./util";

export type SpaceTarget = "challenge" | "me";

type VersionRow = {
  id: string;
  challenge_id: string;
  owner_key: string;
  version: number;
  request: string;
  html: string | null;
  status: "queued" | "building" | "ok" | "failed";
  error: string | null;
  model: string | null;
  duration_ms: number | null;
  author: string;
  created_at: string;
  finished_at: string | null;
};

export function ownerKeyFor(target: SpaceTarget, userId: string) {
  return target === "challenge" ? "" : userId;
}

export function spaceStatus(challengeId: string, ownerKey: string): SpaceStatus {
  const cur = one<VersionRow>(
    `SELECT v.* FROM spaces s JOIN space_versions v ON v.id = s.current_version_id
     WHERE s.challenge_id = ? AND s.owner_key = ?`,
    challengeId,
    ownerKey,
  );
  const pending = one<VersionRow>(
    "SELECT * FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status IN ('queued','building') ORDER BY version DESC LIMIT 1",
    challengeId,
    ownerKey,
  );
  const lastFail = one<VersionRow>(
    "SELECT * FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status = 'failed' ORDER BY version DESC LIMIT 1",
    challengeId,
    ownerKey,
  );
  const count = one<{ n: number }>(
    "SELECT COUNT(*) n FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status = 'ok'",
    challengeId,
    ownerKey,
  )!.n;
  return {
    current: cur ? { id: cur.id, version: cur.version, url: `/s/${cur.id}`, request: cur.request, created_at: cur.created_at } : null,
    pending: pending
      ? { id: pending.id, version: pending.version, status: pending.status as "queued" | "building", request: pending.request, created_at: pending.created_at }
      : null,
    last_failure:
      lastFail && (!cur || lastFail.version > cur.version)
        ? { id: lastFail.id, version: lastFail.version, error: lastFail.error ?? "Unknown error", request: lastFail.request, created_at: lastFail.created_at }
        : null,
    versions: count,
  };
}

export function spaceHistory(challengeId: string, ownerKey: string) {
  return all<Pick<VersionRow, "id" | "version" | "request" | "status" | "created_at" | "author">>(
    "SELECT id, version, request, status, created_at, author FROM space_versions WHERE challenge_id = ? AND owner_key = ? ORDER BY version DESC LIMIT 30",
    challengeId,
    ownerKey,
  );
}

export function getVersion(versionId: string): VersionRow | null {
  return one<VersionRow>("SELECT * FROM space_versions WHERE id = ?", versionId) ?? null;
}

function checkAccess(c: ChallengeRow, user: UserRow, target: SpaceTarget) {
  if (target === "challenge") requireCreator(c, user.id);
  else requireMember(c, user.id);
}

export function requestSpace(user: UserRow, slug: string, target: SpaceTarget, request: string, author = "agent") {
  queue(); // make sure stale-build recovery has run before we add a new build
  const c = getChallenge(slug);
  checkAccess(c, user, target);
  const text = request.trim();
  if (text.length < 8) throw new AppError("invalid", "Describe the space in a sentence or two.");
  const ownerKey = ownerKeyFor(target, user.id);
  const pending = one<{ id: string }>(
    "SELECT id FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status IN ('queued','building')",
    c.id,
    ownerKey,
  );
  if (pending) throw new AppError("conflict", "A version of this space is already being built.", "Wait for it (get_space) before asking again.");
  const today = one<{ n: number }>(
    "SELECT COUNT(*) n FROM space_versions v JOIN challenges c ON c.id = v.challenge_id WHERE v.created_at >= ? AND (v.owner_key = ? OR (v.owner_key = '' AND c.creator_id = ?))",
    new Date(Date.now() - 86400_000).toISOString(),
    user.id,
    user.id,
  )!.n;
  if (today >= 40) throw new AppError("resting", "That's a lot of rebuilds for one day. Try again tomorrow.");
  if (queue().waiting.length >= 30) throw new AppError("resting", "Misogi is building a lot of pages right now. Try again in a few minutes.");
  const versionId = tx(() => {
    const v = (one<{ v: number | null }>("SELECT MAX(version) v FROM space_versions WHERE challenge_id = ? AND owner_key = ?", c.id, ownerKey)!.v ?? 0) + 1;
    const vid = id("spc");
    run(
      `INSERT INTO space_versions (id, challenge_id, owner_key, version, request, status, author, created_at)
       VALUES (?, ?, ?, ?, ?, 'queued', ?, ?)`,
      vid,
      c.id,
      ownerKey,
      v,
      text.slice(0, 2000),
      author,
      nowIso(),
    );
    return vid;
  });
  enqueue(versionId, user.id);
  return { version_id: versionId, status: "queued" as const };
}

export function undoSpace(user: UserRow, slug: string, target: SpaceTarget) {
  const c = getChallenge(slug);
  checkAccess(c, user, target);
  const ownerKey = ownerKeyFor(target, user.id);
  const cur = one<{ current_version_id: string | null }>("SELECT current_version_id FROM spaces WHERE challenge_id = ? AND owner_key = ?", c.id, ownerKey);
  if (!cur?.current_version_id) throw new AppError("not_found", "There's no space to undo yet.");
  const curV = getVersion(cur.current_version_id)!;
  const prev = one<{ id: string; version: number }>(
    "SELECT id, version FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status = 'ok' AND version < ? ORDER BY version DESC LIMIT 1",
    c.id,
    ownerKey,
    curV.version,
  );
  if (!prev) throw new AppError("conflict", "This is the first version; there's nothing to go back to.");
  run("UPDATE spaces SET current_version_id = ? WHERE challenge_id = ? AND owner_key = ?", prev.id, c.id, ownerKey);
  return { current_version: prev.version };
}

export function restoreSpaceVersion(user: UserRow, slug: string, target: SpaceTarget, versionId: string) {
  const c = getChallenge(slug);
  checkAccess(c, user, target);
  const ownerKey = ownerKeyFor(target, user.id);
  const v = getVersion(versionId);
  if (!v || v.challenge_id !== c.id || v.owner_key !== ownerKey || v.status !== "ok") throw new AppError("not_found", "That version can't be restored.");
  run(
    "INSERT INTO spaces (challenge_id, owner_key, current_version_id) VALUES (?, ?, ?) ON CONFLICT(challenge_id, owner_key) DO UPDATE SET current_version_id = excluded.current_version_id",
    c.id,
    ownerKey,
    v.id,
  );
}

// ---------- Background builds ----------

const queueState = globalThis as unknown as {
  __spaceQueue?: { running: number; waiting: { versionId: string; userId: string }[]; recovered: boolean; startedAt: string };
};

function queue() {
  if (!queueState.__spaceQueue) queueState.__spaceQueue = { running: 0, waiting: [], recovered: false, startedAt: nowIso() };
  const q = queueState.__spaceQueue;
  if (!q.recovered) {
    q.recovered = true;
    // Builds left in flight by a previous server process will never finish.
    run(
      "UPDATE space_versions SET status = 'failed', error = 'Interrupted by a server restart. Ask again.', finished_at = ? WHERE status IN ('queued','building') AND created_at < ?",
      nowIso(),
      q.startedAt,
    );
  }
  return q;
}

/** Call once at startup so stale builds are cleaned up before any new request. */
export function initSpaceQueue() {
  queue();
}

const CONCURRENCY = 3;

// Repair context for builds that fix a version which crashed in the browser (kept in memory).
const repairs = globalThis as unknown as { __spaceRepairs?: Map<string, { html: string; error: string }> };
function repairMap() {
  if (!repairs.__spaceRepairs) repairs.__spaceRepairs = new Map();
  return repairs.__spaceRepairs;
}

function enqueue(versionId: string, userId: string) {
  const q = queue();
  q.waiting.push({ versionId, userId });
  pump();
}

function pump() {
  const q = queue();
  while (q.running < CONCURRENCY && q.waiting.length) {
    const job = q.waiting.shift()!;
    q.running++;
    void build(job.versionId, job.userId).finally(() => {
      q.running--;
      pump();
    });
  }
}

async function build(versionId: string, userId: string) {
  const v = getVersion(versionId);
  if (!v || v.status !== "queued") return;
  run("UPDATE space_versions SET status = 'building' WHERE id = ?", versionId);
  const started = Date.now();
  try {
    const c = one<ChallengeRow>("SELECT * FROM challenges WHERE id = ?", v.challenge_id)!;
    const currentHtml = one<{ html: string | null }>(
      `SELECT v.html FROM spaces s JOIN space_versions v ON v.id = s.current_version_id WHERE s.challenge_id = ? AND s.owner_key = ?`,
      v.challenge_id,
      v.owner_key,
    )?.html;
    const repair = repairMap().get(versionId) ?? null;
    repairMap().delete(versionId);
    const { html, model } = await buildSpaceHtml({
      challenge: c,
      ownerUserId: v.owner_key || null,
      request: v.request,
      currentHtml: currentHtml ?? null,
      visitor: userId,
      repair,
    });
    tx(() => {
      run(
        "UPDATE space_versions SET status = 'ok', html = ?, model = ?, duration_ms = ?, finished_at = ? WHERE id = ?",
        html,
        model,
        Date.now() - started,
        nowIso(),
        versionId,
      );
      run(
        "INSERT INTO spaces (challenge_id, owner_key, current_version_id) VALUES (?, ?, ?) ON CONFLICT(challenge_id, owner_key) DO UPDATE SET current_version_id = excluded.current_version_id",
        v.challenge_id,
        v.owner_key,
        versionId,
      );
      // Builds made for demo data aren't something a person did, so they stay out of the feed.
      if (v.author !== "system") recordActivity(v.challenge_id, userId, "space", { version: v.version, target: v.owner_key ? "me" : "challenge" });
    });
  } catch (e) {
    const message = e instanceof AppError ? e.message : "The build failed unexpectedly.";
    if (!(e instanceof AppError)) console.error("[space] build failed", e);
    run(
      "UPDATE space_versions SET status = 'failed', error = ?, duration_ms = ?, finished_at = ? WHERE id = ?",
      message,
      Date.now() - started,
      nowIso(),
      versionId,
    );
  }
}

/**
 * Called when a rendered space reports a runtime error in the browser. A page that `stillShows`
 * (too tall, say) stays up while it's repaired when there's no earlier version to fall back to.
 */
export function reportRenderError(versionId: string, message: string, stillShows = false) {
  const v = getVersion(versionId);
  if (!v || v.status !== "ok") return;
  // Only the newest version can be failed by a report, and only within its first hour,
  // so a stray report can't knock out a page that has worked for a long time.
  const cur = one<{ current_version_id: string }>("SELECT current_version_id FROM spaces WHERE challenge_id = ? AND owner_key = ?", v.challenge_id, v.owner_key);
  if (cur?.current_version_id !== v.id) return;
  if (v.finished_at && Date.now() - new Date(v.finished_at).getTime() > 3600_000) return;
  const prev = one<{ id: string }>(
    "SELECT id FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND status = 'ok' AND version < ? ORDER BY version DESC LIMIT 1",
    v.challenge_id,
    v.owner_key,
    v.version,
  );
  const error = message.slice(0, 300);
  const repairId = tx(() => {
    if (prev || !stillShows) {
      run("UPDATE space_versions SET status = 'failed', error = ? WHERE id = ?", `It broke in the browser: ${error}`, v.id);
      if (prev) run("UPDATE spaces SET current_version_id = ? WHERE challenge_id = ? AND owner_key = ?", prev.id, v.challenge_id, v.owner_key);
      else run("DELETE FROM spaces WHERE challenge_id = ? AND owner_key = ?", v.challenge_id, v.owner_key);
    }
    // Heal once: rebuild the same request with the error fed back to the model.
    if (v.author === "repair" || !v.html) return null;
    const pending = one(
      "SELECT 1 FROM space_versions WHERE challenge_id = ? AND owner_key = ? AND (status IN ('queued','building') OR (author = 'repair' AND version > ?))",
      v.challenge_id,
      v.owner_key,
      v.version,
    );
    if (pending) return null;
    const next = (one<{ n: number | null }>("SELECT MAX(version) n FROM space_versions WHERE challenge_id = ? AND owner_key = ?", v.challenge_id, v.owner_key)!.n ?? 0) + 1;
    const rid = id("spc");
    run(
      `INSERT INTO space_versions (id, challenge_id, owner_key, version, request, status, author, created_at)
       VALUES (?, ?, ?, ?, ?, 'queued', 'repair', ?)`,
      rid,
      v.challenge_id,
      v.owner_key,
      next,
      v.request,
      nowIso(),
    );
    return rid;
  });
  if (repairId) {
    repairMap().set(repairId, { html: v.html!, error });
    const owner = v.owner_key || one<{ creator_id: string }>("SELECT creator_id FROM challenges WHERE id = ?", v.challenge_id)?.creator_id || "";
    enqueue(repairId, owner);
  }
}
